package vn.techzone.backend;

import java.sql.Connection;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.List;

/** Canonical SQLite schema for the 17 entities in Table 20A plus operational histories. */
final class RelationalSchema {
    private RelationalSchema() { }

    static final int VERSION = 1;

    static void create(Connection db) throws SQLException {
        try (Statement s=db.createStatement()) {
            s.execute("PRAGMA foreign_keys=ON");
            for (String sql : List.of(
                    "CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY,applied_at TEXT NOT NULL)",
                    "CREATE TABLE IF NOT EXISTS app_metadata(id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL,active_customer_id TEXT NOT NULL DEFAULT 'CUS-001')",
                    "CREATE TABLE IF NOT EXISTS customers(customer_id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,full_name TEXT NOT NULL,phone_number TEXT NOT NULL DEFAULT '',address TEXT NOT NULL,password_salt BLOB NOT NULL,password_hash BLOB NOT NULL,account_status TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,analytics_consent INTEGER NOT NULL DEFAULT 0 CHECK(analytics_consent IN(0,1)))",
                    "CREATE TABLE IF NOT EXISTS products(product_id TEXT PRIMARY KEY,product_name TEXT NOT NULL,category TEXT NOT NULL,brand_name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',image_url TEXT NOT NULL,created_at TEXT NOT NULL,is_active INTEGER NOT NULL CHECK(is_active IN(0,1)))",
                    "CREATE TABLE IF NOT EXISTS product_variants(variant_id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(product_id),sku TEXT NOT NULL UNIQUE,variant_name TEXT NOT NULL,color TEXT NOT NULL DEFAULT '',capacity TEXT NOT NULL DEFAULT '',price INTEGER NOT NULL CHECK(price>=0),sale_price INTEGER NOT NULL CHECK(sale_price>=0),warranty_months INTEGER NOT NULL CHECK(warranty_months>=0),technical_specs TEXT NOT NULL DEFAULT '{}',is_active INTEGER NOT NULL CHECK(is_active IN(0,1)),updated_at TEXT NOT NULL)",
                    "CREATE TABLE IF NOT EXISTS compatibility_rules(rule_id TEXT PRIMARY KEY,primary_variant_id TEXT NOT NULL REFERENCES product_variants(variant_id),accessory_variant_id TEXT NOT NULL REFERENCES product_variants(variant_id),is_approved INTEGER NOT NULL CHECK(is_approved IN(0,1)),rule_type TEXT NOT NULL,rationale TEXT NOT NULL,verified_by TEXT NOT NULL,verified_at TEXT NOT NULL,UNIQUE(primary_variant_id,accessory_variant_id),CHECK(primary_variant_id<>accessory_variant_id))",
                    "CREATE TABLE IF NOT EXISTS inventory_balances(variant_id TEXT PRIMARY KEY REFERENCES product_variants(variant_id),available_qty INTEGER NOT NULL CHECK(available_qty>=0),reserved_qty INTEGER NOT NULL CHECK(reserved_qty>=0),allocated_qty INTEGER NOT NULL CHECK(allocated_qty>=0),reorder_threshold INTEGER NOT NULL CHECK(reorder_threshold>=0),warehouse_code TEXT NOT NULL,updated_at TEXT NOT NULL)",
                    "CREATE TABLE IF NOT EXISTS inventory_units(unit_id TEXT PRIMARY KEY,variant_id TEXT NOT NULL REFERENCES product_variants(variant_id),serial_imei TEXT NOT NULL UNIQUE,batch_number TEXT NOT NULL,received_at TEXT NOT NULL,warehouse_location TEXT NOT NULL,unit_status TEXT NOT NULL,order_id TEXT REFERENCES sales_orders(order_id))",
                    "CREATE TABLE IF NOT EXISTS shopping_carts(cart_id TEXT PRIMARY KEY,customer_id TEXT NOT NULL UNIQUE REFERENCES customers(customer_id),session_key TEXT NOT NULL UNIQUE,cart_status TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL)",
                    "CREATE TABLE IF NOT EXISTS cart_items(cart_id TEXT NOT NULL REFERENCES shopping_carts(cart_id) ON DELETE CASCADE,variant_id TEXT NOT NULL REFERENCES product_variants(variant_id),quantity INTEGER NOT NULL CHECK(quantity>0),unit_price_snapshot INTEGER NOT NULL CHECK(unit_price_snapshot>=0),added_at TEXT NOT NULL,PRIMARY KEY(cart_id,variant_id))",
                    "CREATE TABLE IF NOT EXISTS sales_orders(order_id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customers(customer_id),order_number TEXT NOT NULL UNIQUE,customer_name TEXT NOT NULL,shipping_address TEXT NOT NULL,payment_method TEXT NOT NULL,order_status TEXT NOT NULL,total_amount INTEGER NOT NULL CHECK(total_amount>=0),currency_code TEXT NOT NULL,tax_amount INTEGER NOT NULL CHECK(tax_amount>=0),shipping_fee INTEGER NOT NULL CHECK(shipping_fee>=0),created_at TEXT NOT NULL,idempotency_key TEXT NOT NULL UNIQUE,subtotal INTEGER NOT NULL DEFAULT 0,discount INTEGER NOT NULL DEFAULT 0,promotion_code TEXT NOT NULL DEFAULT '',payment_reference TEXT NOT NULL DEFAULT '',tracking_code TEXT NOT NULL DEFAULT '',carrier TEXT NOT NULL DEFAULT '',package_weight_grams INTEGER NOT NULL DEFAULT 0,package_dimensions TEXT NOT NULL DEFAULT '',sales_verified_by TEXT NOT NULL DEFAULT '',sales_verified_at TEXT NOT NULL,pending_reason TEXT NOT NULL DEFAULT '',paid_at TEXT NOT NULL,delivered_at TEXT NOT NULL,reconciliation_due_at TEXT NOT NULL)",
                    "CREATE TABLE IF NOT EXISTS order_items(order_item_id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES sales_orders(order_id) ON DELETE CASCADE,variant_id TEXT NOT NULL REFERENCES product_variants(variant_id),quantity INTEGER NOT NULL CHECK(quantity>0),unit_price INTEGER NOT NULL CHECK(unit_price>=0),discount_amount INTEGER NOT NULL DEFAULT 0 CHECK(discount_amount>=0),line_total INTEGER NOT NULL CHECK(line_total>=0),reserved_qty INTEGER NOT NULL DEFAULT 0 CHECK(reserved_qty>=0),allocated_qty INTEGER NOT NULL DEFAULT 0 CHECK(allocated_qty>=0),reservation_state TEXT NOT NULL,reservation_expires_at TEXT NOT NULL,UNIQUE(order_id,variant_id))",
                    "CREATE TABLE IF NOT EXISTS unit_allocations(allocation_id TEXT PRIMARY KEY,order_item_id TEXT NOT NULL REFERENCES order_items(order_item_id),unit_id TEXT NOT NULL UNIQUE REFERENCES inventory_units(unit_id),variant_id TEXT NOT NULL REFERENCES product_variants(variant_id),allocation_status TEXT NOT NULL,allocated_by TEXT NOT NULL,scanned_at TEXT NOT NULL)",
                    "CREATE TABLE IF NOT EXISTS payments(payment_id TEXT PRIMARY KEY,order_id TEXT NOT NULL UNIQUE REFERENCES sales_orders(order_id) ON DELETE CASCADE,payment_method TEXT NOT NULL,provider_ref TEXT NOT NULL,idempotency_key TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>=0),currency_code TEXT NOT NULL,payment_status TEXT NOT NULL,authorized_at TEXT NOT NULL,captured_at TEXT NOT NULL,updated_at TEXT NOT NULL)",
                    "CREATE TABLE IF NOT EXISTS shipments(shipment_id TEXT PRIMARY KEY,order_id TEXT NOT NULL UNIQUE REFERENCES sales_orders(order_id) ON DELETE CASCADE,tracking_code TEXT NOT NULL UNIQUE,carrier_name TEXT NOT NULL,package_weight_grams INTEGER NOT NULL CHECK(package_weight_grams>=0),package_dimensions TEXT NOT NULL,shipped_at TEXT NOT NULL,shipment_status TEXT NOT NULL,delivered_at TEXT NOT NULL)",
                    "CREATE TABLE IF NOT EXISTS warranties(warranty_id TEXT PRIMARY KEY,allocation_id TEXT NOT NULL UNIQUE REFERENCES unit_allocations(allocation_id),activated_at TEXT NOT NULL,expires_at TEXT NOT NULL,coverage_type TEXT NOT NULL,warranty_status TEXT NOT NULL,unit_id TEXT NOT NULL UNIQUE REFERENCES inventory_units(unit_id),variant_id TEXT NOT NULL REFERENCES product_variants(variant_id),order_id TEXT NOT NULL REFERENCES sales_orders(order_id),customer_id TEXT NOT NULL REFERENCES customers(customer_id))",
                    "CREATE TABLE IF NOT EXISTS rma_cases(rma_id TEXT PRIMARY KEY,warranty_id TEXT NOT NULL REFERENCES warranties(warranty_id),customer_id TEXT NOT NULL REFERENCES customers(customer_id),problem_description TEXT NOT NULL,reason_code TEXT NOT NULL,resolution_notes TEXT NOT NULL,closed_at TEXT NOT NULL,rma_status TEXT NOT NULL,created_at TEXT NOT NULL,assigned_to TEXT NOT NULL,diagnosis TEXT NOT NULL,replacement_parts TEXT NOT NULL,updated_at TEXT NOT NULL)",
                    "CREATE TABLE IF NOT EXISTS interaction_events(event_id TEXT PRIMARY KEY,customer_id TEXT REFERENCES customers(customer_id),anonymous_session_key TEXT NOT NULL,variant_id TEXT REFERENCES product_variants(variant_id),request_id TEXT NOT NULL,event_type TEXT NOT NULL,event_source TEXT NOT NULL,consent_scope TEXT NOT NULL,search_query TEXT NOT NULL,filters TEXT NOT NULL,sort_by TEXT NOT NULL,page INTEGER NOT NULL,event_context TEXT NOT NULL,detail TEXT NOT NULL,occurred_at TEXT NOT NULL)",
                    "CREATE TABLE IF NOT EXISTS recommendation_impressions(impression_id TEXT PRIMARY KEY,request_id TEXT NOT NULL,customer_id TEXT NOT NULL REFERENCES customers(customer_id),primary_variant_id TEXT NOT NULL REFERENCES product_variants(variant_id),accessory_variant_id TEXT NOT NULL REFERENCES product_variants(variant_id),rank_position INTEGER NOT NULL CHECK(rank_position>0),score REAL,strategy TEXT NOT NULL,model_version TEXT NOT NULL,generated_at TEXT NOT NULL,shown_at TEXT NOT NULL)",
                    "CREATE TABLE IF NOT EXISTS compatibility_reviews(review_id TEXT PRIMARY KEY,sequence INTEGER NOT NULL UNIQUE,primary_variant_id TEXT NOT NULL REFERENCES product_variants(variant_id),accessory_variant_id TEXT NOT NULL REFERENCES product_variants(variant_id),reason TEXT NOT NULL,created_at TEXT NOT NULL,review_status TEXT NOT NULL,reviewed_by TEXT NOT NULL,review_note TEXT NOT NULL,reviewed_at TEXT NOT NULL)",
                    "CREATE TABLE IF NOT EXISTS market_offers(variant_id TEXT PRIMARY KEY REFERENCES product_variants(variant_id),source_sku TEXT NOT NULL,source_url TEXT NOT NULL,price INTEGER NOT NULL,availability TEXT NOT NULL,fetched_at TEXT NOT NULL)",
                    "CREATE TABLE IF NOT EXISTS warranty_verifications(verification_id TEXT PRIMARY KEY,unit_id TEXT NOT NULL REFERENCES inventory_units(unit_id),customer_id TEXT NOT NULL REFERENCES customers(customer_id),problem TEXT NOT NULL,created_at TEXT NOT NULL,verification_status TEXT NOT NULL,result TEXT NOT NULL)",
                    "CREATE TABLE IF NOT EXISTS shipment_events(event_id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES sales_orders(order_id),milestone TEXT NOT NULL,location TEXT NOT NULL,detail TEXT NOT NULL,occurred_at TEXT NOT NULL)",
                    "CREATE TABLE IF NOT EXISTS notifications(notification_id TEXT PRIMARY KEY,audience TEXT NOT NULL,title TEXT NOT NULL,message TEXT NOT NULL,created_at TEXT NOT NULL,is_read INTEGER NOT NULL CHECK(is_read IN(0,1)))",
                    "CREATE TABLE IF NOT EXISTS consultation_notes(note_id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES sales_orders(order_id),author TEXT NOT NULL,note TEXT NOT NULL,created_at TEXT NOT NULL)",
                    "CREATE TABLE IF NOT EXISTS audit_entries(audit_id INTEGER PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,detail TEXT NOT NULL,occurred_at TEXT NOT NULL)",
                    "CREATE TABLE IF NOT EXISTS restock_requests(restock_id TEXT PRIMARY KEY,variant_id TEXT NOT NULL REFERENCES product_variants(variant_id),quantity INTEGER NOT NULL CHECK(quantity>0),supplier TEXT NOT NULL,created_at TEXT NOT NULL,request_status TEXT NOT NULL,lead_days INTEGER NOT NULL,supplier_reference TEXT NOT NULL)",
                    "CREATE TABLE IF NOT EXISTS supplier_returns(return_id TEXT PRIMARY KEY,variant_id TEXT NOT NULL REFERENCES product_variants(variant_id),unit_id TEXT REFERENCES inventory_units(unit_id),reason TEXT NOT NULL,supplier TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,return_status TEXT NOT NULL)",
                    "CREATE TABLE IF NOT EXISTS product_reviews(review_id INTEGER PRIMARY KEY,reviewer_name TEXT NOT NULL,product_name TEXT NOT NULL,review_text TEXT NOT NULL,rating INTEGER NOT NULL,status TEXT NOT NULL)",
                    "CREATE TABLE IF NOT EXISTS provider_callbacks(provider TEXT NOT NULL,callback_id TEXT NOT NULL,order_id TEXT REFERENCES sales_orders(order_id),PRIMARY KEY(provider,callback_id))",
                    "CREATE TABLE IF NOT EXISTS recommendation_attributions(owner_id TEXT NOT NULL,order_id TEXT NOT NULL DEFAULT '',variant_id TEXT NOT NULL REFERENCES product_variants(variant_id),PRIMARY KEY(owner_id,order_id,variant_id))",
                    "CREATE TABLE IF NOT EXISTS supplier_lead_times(variant_id TEXT PRIMARY KEY REFERENCES product_variants(variant_id),lead_days INTEGER NOT NULL)",
                    "CREATE TABLE IF NOT EXISTS seed_migrations(name TEXT PRIMARY KEY,applied_at TEXT NOT NULL)",
                    "CREATE TABLE IF NOT EXISTS notification_deduplication(variant_id TEXT PRIMARY KEY REFERENCES product_variants(variant_id))",
                    "CREATE TABLE IF NOT EXISTS store_settings(setting_key TEXT PRIMARY KEY,setting_value TEXT NOT NULL)",
                    "CREATE INDEX IF NOT EXISTS idx_variants_product ON product_variants(product_id)",
                    "CREATE INDEX IF NOT EXISTS idx_orders_customer ON sales_orders(customer_id,created_at)",
                    "CREATE INDEX IF NOT EXISTS idx_events_customer_time ON interaction_events(customer_id,occurred_at)",
                    "CREATE INDEX IF NOT EXISTS idx_events_variant_time ON interaction_events(variant_id,occurred_at)",
                    "CREATE INDEX IF NOT EXISTS idx_ship_events_order ON shipment_events(order_id,occurred_at)")) s.execute(sql);
            s.execute("INSERT OR IGNORE INTO schema_migrations(version,applied_at) VALUES("+VERSION+",CURRENT_TIMESTAMP)");
            s.execute("INSERT OR IGNORE INTO app_metadata(id,revision,active_customer_id) VALUES(1,0,'CUS-001')");
        }
    }
}
